from fastapi.security import SecurityScopes, OAuth2PasswordBearer
from fastapi.testclient import TestClient
from fastapi.dependencies.utils import get_parameterless_sub_dependant
from fastapi.dependencies.models import Dependant
oauth = OAuth2PasswordBearer(tokenUrl='token', scopes={'me': 'x', 'items': 'y'})
def inner(s: SecurityScopes, t: str = Depends(oauth)): return {'scopes': [s.scopes]}
def middle(s: SecurityScopes, t: str = Depends(inner)): return s
app = FastAPI()
@app.get('/a')
def a(x: Dependant = Depends(get_parameterless_sub_dependant(depends=Depends(Security(scopes=['me'])), path='a'))):
    return {}
c = TestClient(app)
print(c.get('/a?token=...').json())
" 2>&1 | tail -3; git diff --stat"}

